<?php
declare(strict_types=1);require_once __DIR__.'/../config/api.php';if($_SERVER['REQUEST_METHOD']!=='GET')respond(['success'=>false,'message'=>'Method not allowed'],405);$u=requireUser($pdo);$jobId=(int)($_GET['job_id']??0);$where='a.user_id=?';$params=[$u['user_id']];if($jobId){$where.=' AND a.job_id=?';$params[]=$jobId;}$s=$pdo->prepare("SELECT a.id attendance_id,a.job_id,a.check_in_at,a.check_out_at,a.check_in_latitude,a.check_in_longitude,a.check_in_notes,a.check_out_notes,v.title,h.name hotel_name FROM attendance_records a INNER JOIN jobs j ON j.id=a.job_id INNER JOIN vacancies v ON v.id=j.vacancy_id INNER JOIN hotels h ON h.id=j.hotel_id WHERE $where ORDER BY a.check_in_at DESC");$s->execute($params);respond(['success'=>true,'data'=>$s->fetchAll(PDO::FETCH_ASSOC)]);
